pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount, uint256 firstCalls) public {
        vm.assume(recipient != address(0));
        uint256 calls = bound(firstCalls, 1, 3);
